set local role authenticated;
create temporary table idea_input as select '{"id":"41000000-0000-4000-8000-000000000001","pair_id":"30000000-0000-4000-8000-000000000001","title":"Dinner idea","note":"Try the terrace","link":"https://example.test/dinner"}'::jsonb value;
create temporary table event_input as select '{"id":"42000000-0000-4000-8000-000000000001","pair_id":"30000000-0000-4000-8000-000000000001","title":"Dinner","owner":"together","visibility":"shared","timezone":"Europe/Warsaw","start_date":"2099-01-01","end_date_exclusive":"2099-01-02"}'::jsonb value;
create temporary table saved_idea as select public.create_date_idea((select value from idea_input),'51000000-0000-4000-8000-000000000001') result;
