select is(public.plan_date_idea('41000000-0000-4000-8000-000000000001',(select value||'{"visibility":"private","owner":"a"}' from event_input),1,'51000000-0000-4000-8000-000000000004')->'error'->>'code','VALIDATION','Reject private planned event');
select is((select count(*)::integer from public.events),0,'Failed planning creates no event');
select is((select state from public.date_ideas limit 1),'saved','Failed planning preserves Saved');
