select is((select count(*)::integer from public.date_ideas),0,'Other pair cannot read ideas');
select is(public.plan_date_idea('41000000-0000-4000-8000-000000000001',(select value from event_input),1,'51000000-0000-4000-8000-000000000005')->'error'->>'code','FORBIDDEN','Other pair cannot plan idea');
