select is(public.plan_date_idea('41000000-0000-4000-8000-000000000001',(select value||'{"pair_id":"30000000-0000-4000-8000-000000000002"}' from event_input),1,'51000000-0000-4000-8000-000000000006')->'error'->>'code','FORBIDDEN','Cross-pair plan denied');
create temporary table planned as select public.plan_date_idea('41000000-0000-4000-8000-000000000001',(select value from event_input),1,'51000000-0000-4000-8000-000000000007') result;
