select is((select count(*)::integer from public.events),1,'Plan retry creates one event');
select is(public.plan_date_idea('41000000-0000-4000-8000-000000000001',(select value||'{"id":"42000000-0000-4000-8000-000000000002"}' from event_input),1,'51000000-0000-4000-8000-000000000008')->'error'->>'code','CONFLICT','New command cannot plan the idea twice');
select is(public.update_event('42000000-0000-4000-8000-000000000001',(select value||'{"visibility":"private","owner":"b"}' from event_input),1,'51000000-0000-4000-8000-000000000009')->'error'->>'code','FORBIDDEN','Linked event stays shared');
