create temporary table yearly_input as select '{"id":"43000000-0000-4000-8000-000000000001","pair_id":"30000000-0000-4000-8000-000000000001","title":"Leap birthday","owner":"together","visibility":"shared","timezone":"Europe/Warsaw","start_date":"2024-02-29","end_date_exclusive":"2024-03-01","repeat":"yearly"}'::jsonb value;
