select ok((public.create_date_idea((select value||'{"id":"41000000-0000-4000-8000-000000000003"}' from idea_input),'51000000-0000-4000-8000-000000000015')->>'ok')::boolean,'Create past plan idea');
select ok((public.plan_date_idea('41000000-0000-4000-8000-000000000003',(select value||'{"id":"42000000-0000-4000-8000-000000000003","start_date":"2020-01-01","end_date_exclusive":"2020-01-02"}' from event_input),1,'51000000-0000-4000-8000-000000000016')->>'ok')::boolean,'Plan past event');
select ok((public.delete_event('42000000-0000-4000-8000-000000000003',1,'51000000-0000-4000-8000-000000000017')->>'ok')::boolean,'Delete past event');
